files.content:
.root {
  --vt-surface: #ffffff;
  --vt-surface-2: #fffafa;
  --vt-surface-deep: #2a2a2a;
  --vt-ink: #2a2a2a;
  --vt-ink-soft: #6b6b6b;
  --vt-on-deep: #ffffff;
  --vt-accent: #fb5849;
  --vt-on-accent: #1e1e1e;
  --vt-accent-ink: #fb5849;
  --vt-accent-on-deep: #ffc3be;
  --vt-line: #ece3e1;
  color: var(--vt-ink);
  background: var(--vt-surface);
  font-family: 'Fira Sans', sans-serif;
  line-height: 1.6;
  scroll-behavior: smooth;
  overflow-x: hidden;
}
.root *,
.root *::before,
.root *::after {
  box-sizing: border-box;
}
.root :where(a) {
  color: inherit;
  text-decoration: none;
}
.root :where(h1, h2, h3, h4, h5, h6) {
  font-family: 'Syne', sans-serif;
  line-height: 1.2;
}
.root :where(img) {
  max-width: 100%;
  display: block;
}
.root a:focus-visible {
  outline: 2px solid var(--vt-accent);
  outline-offset: 2px;
}

.nav {
  position: relative;
  z-index: 20;
  background: var(--vt-surface);
  border-bottom: 1px solid var(--vt-line);
}
.navIn {
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 72px;
}
.logo {
  display: inline-flex;
  align-items: center;
  color: var(--vt-ink);
}
.brand {
  font-family: 'Syne', sans-serif;
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: 0.02em;
}
.navLinks {
  display: flex;
  gap: 24px;
  align-items: center;
  flex-wrap: wrap;
}
.navLinks a {
  font-size: 0.875rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--vt-ink);
  padding: 8px 0;
  border-bottom: 2px solid transparent;
  transition: color 0.2s ease, border-color 0.2s ease;
}
.navLinks a:hover {
  color: var(--vt-accent-ink);
  border-color: var(--vt-accent);
}

.hero {
  display: grid;
  grid-template-columns: minmax(320px, 5fr) minmax(0, 7fr);
  min-height: 640px;
  background: var(--vt-surface-deep);
}
.heroPanel {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 80px 48px;
  background: linear-gradient(rgba(0, 0, 0, 0.25), rgba(0, 0, 0, 0.25)), var(--vt-surface-deep);
  color: var(--vt-on-deep);
}
.heroInner {
  max-width: 360px;
}
.heroBrand {
  font-family: 'Syne', sans-serif;
  font-size: 1.25rem;
  color: var(--vt-on-deep);
  margin-bottom: 12px;
}
.heroTitle {
  font-size: clamp(2.5rem, 6vw, 4.5rem);
  color: var(--vt-on-deep);
  margin: 0;
}
.heroKicker {
  text-transform: uppercase;
  letter-spacing: 0.2em;
  font-size: 0.875rem;
  color: var(--vt-accent-on-deep);
  margin-top: 8px;
}
.heroButton {
  display: inline-block;
  margin-top: 28px;
  background: var(--vt-surface);
  color: var(--vt-accent-ink);
  font-weight: 700;
  font-size: 0.875rem;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  padding: 14px 28px;
  border-radius: 4px;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}
.heroButton:hover {
  transform: translateY(-2px);
  box-shadow: 0 10px 25px rgba(0, 0, 0, 0.15);
}
.heroSlides {
  display: flex;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  background: var(--vt-surface-deep);
  scrollbar-width: none;
}
.heroSlides::-webkit-scrollbar {
  display: none;
}
.heroSlide {
  position: relative;
  flex: 0 0 100%;
  scroll-snap-align: start;
  min-height: 640px;
}
.heroSlide img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.about {
  padding: 100px 24px;
  max-width: 1280px;
  margin: 0 auto;
}
.aboutGrid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}
.eyebrow {
  position: relative;
  color: var(--vt-accent-ink);
  text-transform: uppercase;
  letter-spacing: 0.18em;
  font-size: 0.8rem;
  font-weight: 700;
  padding-left: 36px;
}
.eyebrow::before {
  content: '';
  position: absolute;
  left: 0;
  top: 50%;
  width: 24px;
  height: 1px;
  background: var(--vt-accent);
}
.title {
  font-size: clamp(1.8rem, 3vw, 2.5rem);
  margin: 12px 0 20px;
  color: var(--vt-ink);
}
.paragraph {
  color: var(--vt-ink-soft);
  margin-bottom: 16px;
  max-width: 58ch;
}
.aboutVisual {
  display: grid;
  grid-template-columns: 1.2fr 1fr;
  gap: 16px;
  align-items: center;
}
.aboutMain {
  grid-row: span 3;
}
.aboutMain img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  border-radius: 8px;
  box-shadow: 0 20px 40px rgba(0, 0, 0, 0.08);
}
.aboutThumbs {
  display: grid;
  gap: 16px;
}
.aboutThumbs img {
  width: 100%;
  aspect-ratio: 4 / 3;
  object-fit: cover;
  border-radius: 6px;
}

.menu {
  background: var(--vt-surface-2);
  padding: 100px 24px;
}
.sectionHead {
  max-width: 1280px;
  margin: 0 auto 56px;
}
.menuRow {
  display: flex;
  gap: 24px;
  overflow-x: auto;
  padding-bottom: 16px;
  scroll-snap-type: x mandatory;
  max-width: 1280px;
  margin: 0 auto;
  scrollbar-width: none;
}
.menuRow::-webkit-scrollbar {
  display: none;
}
.menuCard {
  position: relative;
  flex: 0 0 280px;
  background: var(--vt-surface);
  border-radius: 10px;
  overflow: hidden;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.06);
  scroll-snap-align: start;
  transition: transform 0.3s ease, box-shadow 0.3s ease;
}
.menuCard:hover {
  transform: translateY(-6px);
  box-shadow: 0 16px 32px rgba(0, 0, 0, 0.1);
}
.menuImage {
  width: 100%;
  aspect-ratio: 4 / 3;
  object-fit: cover;
  transition: transform 0.4s ease;
}
.menuCard:hover .menuImage {
  transform: scale(1.04);
}
.menuNum {
  position: absolute;
  top: 12px;
  right: 12px;
  width: 44px;
  height: 44px;
  background: var(--vt-accent);
  color: var(--vt-on-accent);
  font-family: 'Syne', sans-serif;
  font-weight: 700;
  display: grid;
  place-items: center;
  border-radius: 6px;
}
.menuBody {
  padding: 18px;
}
.menuTitle {
  font-size: 1.15rem;
  margin-bottom: 8px;
  color: var(--vt-ink);
}
.menuDesc {
  font-size: 0.9rem;
  color: var(--vt-ink-soft);
  margin-bottom: 14px;
}
.menuLink {
  font-size: 0.8rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--vt-accent-ink);
}
.menuLink:hover {
  text-decoration: underline;
}

.gallery {
  padding: 100px 24px;
  max-width: 1280px;
  margin: 0 auto;
}
.galleryGrid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}
.galleryItem {
  position: relative;
  overflow: hidden;
  border-radius: 10px;
  margin: 0;
}
.galleryItem img {
  display: block;
  width: 100%;
  height: 100%;
  aspect-ratio: 4 / 5;
  object-fit: cover;
  transition: transform 0.4s ease;
}
.galleryItem:hover img {
  transform: scale(1.04);
}
.galleryItem figcaption {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  padding: 40px 16px 14px;
  color: var(--vt-on-deep);
  background: linear-gradient(transparent, rgba(0, 0, 0, 0.65));
  font-weight: 600;
}

.contact {
  background: var(--vt-surface-deep);
  padding: 100px 24px;
  color: var(--vt-on-deep);
}
.contactInner {
  max-width: 1280px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 56px;
  align-items: center;
}
.contact .eyebrow {
  color: var(--vt-accent-on-deep);
}
.contact .eyebrow::before {
  background: var(--vt-accent-on-deep);
}
.contact .title {
  color: var(--vt-on-deep);
}
.contactCard {
  background: var(--vt-surface);
  border-radius: 10px;
  padding: 40px;
  color: var(--vt-ink);
  box-shadow: 0 20px 40px rgba(0, 0, 0, 0.2);
}
.contactCardTitle {
  font-size: 1.4rem;
  margin-bottom: 12px;
}
.contactCardText {
  color: var(--vt-ink-soft);
  margin-bottom: 16px;
}

.footer {
  background: var(--vt-accent);
  color: var(--vt-on-accent);
  padding: 48px 24px;
}
.footerIn {
  max-width: 1280px;
  margin: 0 auto;
  display: flex;
  flex-wrap: wrap;
  gap: 24px;
  align-items: center;
  justify-content: space-between;
}
.footerBrand {
  font-family: 'Syne', sans-serif;
  font-size: 1.25rem;
}
.footerText {
  margin: 0;
  font-size: 0.875rem;
}

@media (max-width: 960px) {
  .hero {
    grid-template-columns: 1fr;
  }
  .heroPanel {
    min-height: 380px;
  }
  .heroSlide {
    min-height: 380px;
  }
  .aboutGrid,
  .contactInner {
    grid-template-columns: 1fr;
  }
  .galleryGrid {
    grid-template-columns: repeat(2, 1fr);
  }
}
@media (max-width: 640px) {
  .navIn {
    flex-wrap: wrap;
    justify-content: center;
    gap: 8px;
    padding-top: 10px;
    padding-bottom: 10px;
  }
  .navLinks {
    justify-content: center;
    gap: 8px;
  }
  .navLinks a {
    font-size: 0.78rem;
    letter-spacing: 0.03em;
    padding: 6px 8px;
  }
  .about,
  .menu,
  .gallery,
  .contact {
    padding: 72px 18px;
  }
  .heroPanel {
    padding: 40px 24px;
  }
  .galleryGrid {
    grid-template-columns: 1fr;
  }
  .menuCard {
    flex: 0 0 260px;
  }
  .contactCard {
    padding: 28px 20px;
  }
  .footerIn {
    justify-content: center;
    text-align: center;
  }
}
@media (prefers-reduced-motion: reduce) {
  .root {
    scroll-behavior: auto;
  }
  .menuCard,
  .galleryItem img,
  .heroButton {
    transition: none;
  }
}
